    def regex_ilike(self, pattern: str, text: str) -> bool:
        """Construct a regex pattern for ILIKE operation and match against the text."""
        parts = []
        position = 0
        while position < len(pattern):
            char = pattern[position]
            if char == '\\' and position + 1 < len(pattern):
                # Infobase uses backslash to escape a LIKE wildcard.
                position += 1
                parts.append(re.escape(pattern[position]))
            elif char == '*':
                parts.append('.*')
            elif char != '_':
                parts.append(re.escape(char))
            position += 1
        regex_pattern = '^' + ''.join(parts) + '$'
        return bool(re.match(regex_pattern, text, re.IGNORECASE))

